import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Row, Col, Label, FormGroup } from 'reactstrap';
import { Paper } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import Skeleton from '@material-ui/lab/Skeleton';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import CustomInput from 'views/admin/Common/CustomInput';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import Pagination from 'views/admin/Common/Pagination';
import NoMatchPage from 'views/admin/Common/NoMatchPage.jsx';
import {
  USER_TYPES,
  fetchAppUsageReportService,
  fetchAppUsageSummaryService,
  fetchNotInstalledService,
  fetchLatestAppVersionService,
  blockAppUserService,
  unblockAppUserService,
} from 'actions/admin/appUsage';
import { showToast } from 'actions/admin/auth';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import {
  VERSION_STATE,
  formatDaysAgo,
  getAccessMeta,
  getLastLoginColor,
  getVersionState,
  isNewerVersion,
  studentChipLabel,
} from 'utils/appUsage';
import constants, { employeeStatic } from 'config/constants';
import colors from 'config/colors';
import StatTile from 'views/admin/Common/StatTile';

const PAGE_SIZE = 20;

const TABS = { USERS: 'USERS', NOT_INSTALLED: 'NOT_INSTALLED' };

// "Show" filter -> the backend's blocked / inactiveDays params. An account is Active (it can log in) or Inactive
// (the admin switched its login off, e.g. for a teacher who left); "not logged in" is only about the last login.
const ACTIVITY_OPTIONS = [
  { label: 'All users', value: 'ALL' },
  { label: 'Inactive accounts', value: 'BLOCKED' },
  { label: 'Not logged in for 7+ days', value: 'INACTIVE_7' },
  { label: 'Not logged in for 30+ days', value: 'INACTIVE_30' },
  { label: 'Not logged in for 90+ days', value: 'INACTIVE_90' },
];

const ACTIVITY_PARAMS = {
  ALL: {},
  BLOCKED: { blocked: true },
  INACTIVE_7: { inactiveDays: 7 },
  INACTIVE_30: { inactiveDays: 30 },
  INACTIVE_90: { inactiveDays: 90 },
};

const USER_TYPE_OPTIONS = [{ label: 'All types', value: '' }, ...USER_TYPES];

const userTypeLabel = value => USER_TYPES.find(el => el.value === value)?.label.replace(/s$/, '') || '--';

// Wrapped like CustomInput (FormGroup + form-label) so the select's label and box line up with the inputs next to it.
const FieldSelect = ({ label, ...props }) => (
  <FormGroup>
    <Label className="form-label">{label}</Label>
    <CustomSelect noLabel {...props} />
  </FormGroup>
);

const Badge = ({ color, background, children }) => (
  <span
    style={{
      display: 'inline-block',
      padding: '2px 10px',
      borderRadius: 12,
      fontSize: 12,
      fontWeight: 'bold',
      color,
      background,
      whiteSpace: 'nowrap',
    }}>
    {children}
  </span>
);

const StatusBadge = ({ blocked }) => {
  const meta = getAccessMeta(blocked);
  return (
    <Badge color={meta.color} background={meta.background}>
      {meta.label}
    </Badge>
  );
};

const VersionCell = ({ version, latestVersion }) => {
  const state = getVersionState(version, latestVersion);
  return (
    <div style={{ whiteSpace: 'nowrap' }}>
      <b>{version || '--'}</b>{' '}
      {state === VERSION_STATE.LATEST && (
        <Badge color="#2e7d32" background="#e8f5e9">
          Latest
        </Badge>
      )}
      {state === VERSION_STATE.OLD && (
        <Badge color="#b26a00" background="#fff3e0">
          Update available
        </Badge>
      )}
    </div>
  );
};

const USER_HEADERS = ['Name', 'Students', 'Mobile / Login', 'App version', 'Last login', 'Logins', 'Status', 'Action'];
// Who a login is, as a coloured pill beside the name. `role` comes from the backend; older rows fall back to the user type.
const ROLE_LOOKS = {
  GUARD: { label: 'Guardian', color: '#6a1b9a', background: '#f3e5f5' },
  TEACHER: { label: employeeStatic, color: '#1565c0', background: '#e3f2fd' },
  ADMIN: { label: 'Admin', color: '#e65100', background: '#fff3e0' },
  SUPER_ADMIN: { label: 'Admin', color: '#e65100', background: '#fff3e0' },
  DEAN: { label: 'Dean', color: '#00695c', background: '#e0f2f1' },
  DRIVER: { label: 'Driver', color: '#5d4037', background: '#efebe9' },
};
const roleLook = item =>
  ROLE_LOOKS[item.role] ||
  (item.userType === 'GUARDIAN'
    ? ROLE_LOOKS.GUARD
    : { label: userTypeLabel(item.userType), color: '#546e7a', background: '#eceff1' });

const RolePill = ({ item }) => {
  const look = roleLook(item);
  return (
    <span
      style={{
        display: 'inline-block',
        marginTop: 3,
        padding: '0 8px',
        borderRadius: 10,
        fontSize: 10.5,
        fontWeight: 'bold',
        letterSpacing: 0.3,
        color: look.color,
        background: look.background,
        whiteSpace: 'nowrap',
      }}>
      {look.label}
    </span>
  );
};

const NOT_INSTALLED_HEADERS = ['Guardian', 'Students', 'Mobile', 'Email'];

// A guardian's students (one guardian can have several), as small pills.
const StudentChips = ({ names }) =>
  names?.length ? (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 4, marginTop: 4 }}>
      {names.map((student, i) => (
        <span
          key={`${studentChipLabel(student)}-${i}`}
          style={{
            fontSize: 11,
            fontWeight: 600,
            color: colors.accentDark,
            background: `${colors.accent}14`,
            borderRadius: 10,
            padding: '1px 8px',
            whiteSpace: 'nowrap',
          }}>
          {studentChipLabel(student)}
        </span>
      ))}
    </div>
  ) : (
    '--'
  );

const TableSkeleton = ({ headers }) =>
  Array.from({ length: 5 }).map((_, i) => (
    <TableRow key={i}>
      {headers.map(header => (
        <TableCell key={header}>
          <Skeleton variant="text" />
        </TableCell>
      ))}
    </TableRow>
  ));

const EmptyRow = ({ colSpan, children }) => (
  <TableRow>
    <TableCell colSpan={colSpan} style={{ textAlign: 'center', color: '#9a9a9a' }}>
      {children}
    </TableCell>
  </TableRow>
);

// Admin-only view of who uses the mobile app: version (latest or not), last login, active / inactive account, and
// mark active / inactive. The sidebar entry is limited to the admin role in AdminRoutes.jsx, but AdminApp doesn't check
// accessRoles for a plain route, so a direct URL is turned away here as well.
const AppUsagePage = () => {
  const dispatch = useDispatch();
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const loggedUserSchool = useSelector(state => state.auth.loggedUserSchool);
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const isAdmin = loggedUserRole === constants.roles.admin;
  const schoolId = loggedUserSchool || getGlobalSchoolUtils()?.schoolId;

  const [tab, setTab] = useState(TABS.USERS);
  const [activity, setActivity] = useState('ALL');
  const [userType, setUserType] = useState('');
  const [appVersion, setAppVersion] = useState('');
  const [searchText, setSearchText] = useState('');
  const [search, setSearch] = useState('');
  const [pageIndex, setPageIndex] = useState(0);

  const [summary, setSummary] = useState(null);
  const [isSummaryFetching, setIsSummaryFetching] = useState(false);
  const [latestVersion, setLatestVersion] = useState(null);
  const [list, setList] = useState(null);
  const [isFetching, setIsFetching] = useState(false);
  const [loadError, setLoadError] = useState('');

  const [pendingUser, setPendingUser] = useState(null);
  const [isActing, setIsActing] = useState(false);

  const showWarning = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);

  // The search box feeds the backend only after a pause, and always from page 1.
  useEffect(() => {
    const timer = setTimeout(() => {
      setSearch(searchText.trim());
      setPageIndex(0);
    }, 400);
    return () => clearTimeout(timer);
  }, [searchText]);

  useEffect(() => {
    if (!isAdmin) return;
    fetchLatestAppVersionService({ token: loggedUserToken })
      .then(data => setLatestVersion(data?.versionName || null))
      .catch(err => console.error('err-fetchLatestAppVersionService', err));
  }, [isAdmin, loggedUserToken]);

  const fetchSummary = useCallback(() => {
    if (!isAdmin || !schoolId) return;
    setIsSummaryFetching(true);
    fetchAppUsageSummaryService({ schoolId, token: loggedUserToken })
      .then(data => setSummary(data))
      .catch(err => {
        setSummary(null);
        showWarning(formResMessage(err), 'error');
      })
      .finally(() => setIsSummaryFetching(false));
  }, [isAdmin, schoolId, loggedUserToken, showWarning]);

  useEffect(() => {
    fetchSummary();
  }, [fetchSummary]);

  // A late answer for an earlier filter must not overwrite the list the admin is looking at now.
  const requestId = useRef(0);
  const fetchList = useCallback(() => {
    if (!isAdmin || !schoolId) return;
    const current = ++requestId.current;
    setIsFetching(true);
    setLoadError('');
    const request =
      tab === TABS.NOT_INSTALLED
        ? fetchNotInstalledService({ schoolId, page: pageIndex, size: PAGE_SIZE, token: loggedUserToken })
        : fetchAppUsageReportService({
            schoolId,
            userType,
            appVersion,
            search,
            ...ACTIVITY_PARAMS[activity],
            page: pageIndex,
            size: PAGE_SIZE,
            token: loggedUserToken,
          });
    request
      .then(data => {
        if (current === requestId.current) setList(data);
      })
      .catch(err => {
        if (current !== requestId.current) return;
        setList(null);
        setLoadError(formResMessage(err));
      })
      .finally(() => {
        if (current === requestId.current) setIsFetching(false);
      });
  }, [isAdmin, schoolId, tab, userType, appVersion, search, activity, pageIndex, loggedUserToken]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  const changeFilter = setter => (name, value) => {
    setter(value);
    setPageIndex(0);
  };

  const switchTab = nextTab => {
    if (nextTab === tab) return;
    setTab(nextTab);
    setList(null);
    setPageIndex(0);
  };

  // Tiles double as shortcuts to the matching list.
  const showUsers = (nextActivity, nextVersion = '') => {
    setTab(TABS.USERS);
    setActivity(nextActivity);
    setUserType('');
    setAppVersion(nextVersion);
    setSearchText('');
    setSearch('');
    setPageIndex(0);
    setList(null);
  };

  const confirmAction = () => {
    if (!pendingUser) return;
    const { user, block } = pendingUser;
    setIsActing(true);
    (block ? blockAppUserService : unblockAppUserService)({ userId: user.userId, token: loggedUserToken })
      .then(() => {
        showWarning(
          block
            ? `${user.name || user.username} is now inactive and can't log in`
            : `${user.name || user.username} is active again`,
          'success'
        );
        setPendingUser(null);
        fetchList();
        fetchSummary();
      })
      .catch(err => {
        showWarning(formResMessage(err), 'error');
        setPendingUser(null);
        // The list may be stale (someone else changed it first), so show what the server has now.
        fetchList();
        fetchSummary();
      })
      .finally(() => setIsActing(false));
  };

  const versionOptions = useMemo(() => {
    const counts = summary?.versionWiseCount || {};
    const versions = Object.keys(counts)
      .filter(version => version !== 'UNKNOWN')
      .sort((a, b) => (isNewerVersion(a, b) ? -1 : 1));
    const older = latestVersion ? versions.filter(version => isNewerVersion(latestVersion, version)) : [];
    return [
      { label: 'All versions', value: '' },
      // set by the "On an older version" card
      ...(older.length > 1
        ? [{ label: `All older versions - ${older.reduce((sum, v) => sum + counts[v], 0)}`, value: older.join(',') }]
        : []),
      ...versions.map(version => ({
        label: `${version}${version === latestVersion ? ' (latest)' : ''} - ${counts[version]}`,
        value: version,
      })),
    ];
  }, [summary, latestVersion]);

  if (!isAdmin) return <NoMatchPage />;

  const counts = summary?.versionWiseCount || {};
  const onLatest = latestVersion ? counts[latestVersion] || 0 : null;
  const olderVersions = latestVersion
    ? Object.keys(counts).filter(version => version !== 'UNKNOWN' && isNewerVersion(latestVersion, version))
    : [];
  const onOlder = latestVersion ? olderVersions.reduce((sum, version) => sum + counts[version], 0) : null;
  // the "older" card filters by every older version at once (the backend takes them comma separated)
  const olderFilter = olderVersions.join(',');

  const rows = list?.content || [];
  const headers = tab === TABS.NOT_INSTALLED ? NOT_INSTALLED_HEADERS : USER_HEADERS;
  const tabStyle = isActive => ({
    padding: '6px 16px',
    marginRight: 8,
    borderRadius: 18,
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: 13,
    color: isActive ? colors.white : colors.accent,
    background: isActive ? colors.accent : '#f5f2f8',
  });

  return (
    <div className="content">
      <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0', marginBottom: 16 }}>
        <div className="card-category font-weight-bold mb-3" style={{ overflow: 'hidden' }}>
          App Usage
          <span style={{ float: 'right', fontWeight: 'normal', fontSize: 13, color: '#6b778a' }}>
            Latest app version: <b style={{ color: colors.grey1 }}>{latestVersion || '--'}</b>
          </span>
        </div>
        <div style={{ display: 'flex', flexWrap: 'nowrap', gap: 10, overflowX: 'auto', paddingBottom: 4 }}>
          <StatTile
            label="Users on the app"
            value={summary?.totalUsers ?? 0}
            loading={isSummaryFetching}
            onClick={() => showUsers('ALL')}
            active={tab === TABS.USERS && activity === 'ALL' && !appVersion}
          />
          <StatTile
            label="Guardians not installed"
            value={summary?.guardiansNotInstalled ?? 0}
            note="Never logged in"
            loading={isSummaryFetching}
            onClick={() => switchTab(TABS.NOT_INSTALLED)}
            active={tab === TABS.NOT_INSTALLED}
          />
          <StatTile
            label="On latest version"
            value={onLatest ?? '--'}
            tone="good"
            note={latestVersion ? `Version ${latestVersion}` : 'No release published'}
            loading={isSummaryFetching}
            onClick={latestVersion ? () => showUsers('ALL', latestVersion) : undefined}
            active={tab === TABS.USERS && !!latestVersion && appVersion === latestVersion}
          />
          <StatTile
            label="On an older version"
            value={onOlder ?? '--'}
            tone="warn"
            loading={isSummaryFetching}
            onClick={olderFilter ? () => showUsers('ALL', olderFilter) : undefined}
            active={tab === TABS.USERS && !!olderFilter && appVersion === olderFilter}
          />
          <StatTile
            label="No login 7+ days"
            value={summary?.inactive7Days ?? 0}
            tone="warn"
            loading={isSummaryFetching}
            onClick={() => showUsers('INACTIVE_7')}
            active={tab === TABS.USERS && activity === 'INACTIVE_7'}
          />
          <StatTile
            label="No login 30+ days"
            value={summary?.inactive30Days ?? 0}
            tone="bad"
            loading={isSummaryFetching}
            onClick={() => showUsers('INACTIVE_30')}
            active={tab === TABS.USERS && activity === 'INACTIVE_30'}
          />
          <StatTile
            label="Inactive accounts"
            value={summary?.blockedUsers ?? 0}
            tone="bad"
            loading={isSummaryFetching}
            onClick={() => showUsers('BLOCKED')}
            active={tab === TABS.USERS && activity === 'BLOCKED'}
          />
        </div>
      </Paper>

      <Paper elevation={0} style={{ padding: 20, border: '3px solid #e0e0e0' }}>
        <div className="mb-3">
          <span role="button" style={tabStyle(tab === TABS.USERS)} onClick={() => switchTab(TABS.USERS)}>
            App users
          </span>
          <span
            role="button"
            style={tabStyle(tab === TABS.NOT_INSTALLED)}
            onClick={() => switchTab(TABS.NOT_INSTALLED)}>
            Not installed
          </span>
        </div>

        {tab === TABS.USERS && (
          <Row>
            <Col sm={6} md={3}>
              <FieldSelect
                label="Show"
                name="activity"
                value={activity}
                options={ACTIVITY_OPTIONS}
                onChange={changeFilter(setActivity)}
              />
            </Col>
            <Col sm={6} md={2}>
              <FieldSelect
                label="User type"
                name="userType"
                value={userType}
                options={USER_TYPE_OPTIONS}
                onChange={changeFilter(setUserType)}
              />
            </Col>
            <Col sm={6} md={3}>
              <FieldSelect
                label="App version"
                name="appVersion"
                value={appVersion}
                options={versionOptions}
                onChange={changeFilter(setAppVersion)}
              />
            </Col>
            <Col sm={6} md={4}>
              <CustomInput
                label="Search"
                name="searchText"
                placeholder="Name, login or mobile..."
                value={searchText}
                onChange={(n, v) => setSearchText(v)}
              />
            </Col>
          </Row>
        )}
        {tab === TABS.NOT_INSTALLED && (
          <div style={{ fontSize: 13, color: '#6b778a', marginBottom: 12 }}>
            Guardians of this school who have never logged in from the mobile app.
          </div>
        )}

        {!!loadError && <div className="err-msg mb-3">{loadError}</div>}

        <div style={{ overflowX: 'auto' }}>
          <Table size="small" aria-label="app usage">
            <TableHead>
              <TableRow style={{ backgroundColor: '#e0e0e0' }}>
                {headers.map(header => (
                  <TableCell key={header} component="th" align="left">
                    <b>{header}</b>
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {isFetching && !rows.length ? (
                <TableSkeleton headers={headers} />
              ) : !rows.length ? (
                <EmptyRow colSpan={headers.length}>
                  {tab === TABS.NOT_INSTALLED
                    ? 'Every guardian has logged in from the app.'
                    : 'No users match these filters yet. Users appear here after they log in from the mobile app.'}
                </EmptyRow>
              ) : tab === TABS.NOT_INSTALLED ? (
                rows.map(item => (
                  <TableRow key={item.guardianId}>
                    <TableCell>{item.name || '--'}</TableCell>
                    <TableCell style={{ minWidth: 230 }}>
                      <StudentChips names={item.students} />
                    </TableCell>
                    <TableCell>{item.mobile || '--'}</TableCell>
                    <TableCell>{item.email || '--'}</TableCell>
                  </TableRow>
                ))
              ) : (
                rows.map(item => {
                  const isSelf = String(item.userId) === String(loggedUserId);
                  return (
                    <TableRow key={item.userId} style={item.blocked ? { backgroundColor: '#fff5f5' } : undefined}>
                      <TableCell>
                        <div>{item.name || '--'}</div>
                        <div style={{ fontSize: 11, color: '#6b778a' }}>{item.username}</div>
                        <RolePill item={item} />
                      </TableCell>
                      <TableCell style={{ minWidth: 230 }}>
                        <StudentChips names={item.students} />
                      </TableCell>
                      <TableCell>{item.mobile || '--'}</TableCell>
                      <TableCell>
                        <VersionCell version={item.appVersion} latestVersion={latestVersion} />
                      </TableCell>
                      <TableCell style={{ whiteSpace: 'nowrap' }}>
                        <div>
                          {item.lastLoginDate ? moment(item.lastLoginDate).format('DD MMM, YYYY hh:mm A') : '--'}
                        </div>
                        <div style={{ fontSize: 11, color: getLastLoginColor(item.daysSinceLastLogin) }}>
                          {formatDaysAgo(item.daysSinceLastLogin)}
                        </div>
                      </TableCell>
                      <TableCell>{item.loginCount ?? 0}</TableCell>
                      <TableCell>
                        <StatusBadge blocked={item.blocked} />
                        {item.blocked && item.blockedDate && (
                          <div style={{ fontSize: 11, color: '#6b778a', marginTop: 2 }}>
                            Since {moment(item.blockedDate).format('DD MMM, YYYY')}
                            {item.blockedBy ? ` by ${item.blockedBy}` : ''}
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        {isSelf ? (
                          <span style={{ fontSize: 12, color: '#9a9a9a' }}>You</span>
                        ) : item.blocked ? (
                          <CustomButton
                            size="small"
                            style={{ whiteSpace: 'nowrap' }}
                            name="Mark active"
                            onClick={() => setPendingUser({ user: item, block: false })}
                          />
                        ) : (
                          <CustomButton
                            size="small"
                            style={{ whiteSpace: 'nowrap' }}
                            color="danger"
                            name="Mark inactive"
                            onClick={() => setPendingUser({ user: item, block: true })}
                          />
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </div>

        {!!rows.length && (
          <Pagination
            style={{ marginTop: 16 }}
            {...list}
            isLoading={isFetching}
            fetchPageData={pageNum => setPageIndex(pageNum - 1)}
          />
        )}
      </Paper>

      <ConfirmModal
        size="md"
        loading={isActing}
        confirmModalOpen={!!pendingUser}
        deleteConfirm={confirmAction}
        deleteCancel={() => setPendingUser(null)}
        confirmMessage={
          pendingUser?.block
            ? `Mark ${
                pendingUser.user.name || pendingUser.user.username
              } inactive? They will not be able to log in to the app until you mark them active again.`
            : `Mark ${
                pendingUser?.user.name || pendingUser?.user.username
              } active? They can log in again with their old password.`
        }
      />
    </div>
  );
};

export default AppUsagePage;
