import axios from 'axios';
import constants from 'config/constants';

// App usage (admin): who has logged in from the mobile app, on which app version, and when - plus block / unblock.
// Plain async calls (no reducer): only the admin-only App usage page uses them.
const BASE = `${constants.API_BASE_URL}/api/admin/app-usage`;

export const USER_TYPES = [
  { label: 'Guardians', value: 'GUARDIAN' },
  { label: 'Staff', value: 'EMPLOYEE' },
  { label: 'Other', value: 'OTHER' },
];

// Params left empty are not sent, so the backend applies no filter for them.
const clean = params =>
  Object.keys(params).reduce((acc, key) => {
    const value = params[key];
    if (value !== undefined && value !== null && value !== '') acc[key] = value;
    return acc;
  }, {});

// -> Spring page { content: [user], page: { size, number, totalElements, totalPages } }. `page` is 0-based.
export const fetchAppUsageReportService = async ({
  schoolId,
  userType,
  appVersion,
  inactiveDays,
  blocked,
  search,
  page = 0,
  size = 20,
  token,
}) => {
  const params = clean({ schoolId, userType, appVersion, inactiveDays, blocked, search, page, size });
  const res = await axios.get(`${BASE}/report${constants.makeParams(params)}`, constants.setHeader(token));
  return res.data;
};

// -> { versionWiseCount: { '2.8': 12 }, totalUsers, blockedUsers, inactive7Days, inactive30Days, guardiansNotInstalled }
export const fetchAppUsageSummaryService = async ({ schoolId, token }) => {
  const res = await axios.get(
    `${BASE}/summary${constants.makeParams(clean({ schoolId }))}`,
    constants.setHeader(token)
  );
  return res.data;
};

// Guardians of the school who never logged in from the app. -> Spring page of { guardianId, name, mobile, email }.
export const fetchNotInstalledService = async ({ schoolId, page = 0, size = 20, token }) => {
  const res = await axios.get(
    `${BASE}/not-installed${constants.makeParams({ schoolId, page, size })}`,
    constants.setHeader(token)
  );
  return res.data;
};

// Block: the user's login stops working until they are unblocked (the backend keeps their password aside).
export const blockAppUserService = async ({ userId, token }) => {
  const res = await axios.put(`${BASE}/${userId}/block`, null, constants.setHeader(token));
  return res.data;
};

export const unblockAppUserService = async ({ userId, token }) => {
  const res = await axios.put(`${BASE}/${userId}/unblock`, null, constants.setHeader(token));
  return res.data;
};

// The newest published app release - the same call the mobile app makes to decide whether to ask for an update.
// -> { versionName, versionCode, releaseDate, description } or null when none is published.
export const fetchLatestAppVersionService = async ({ token }) => {
  const res = await axios.get(`${constants.API_BASE_URL}/api/recent/app-version-info`, constants.setHeader(token));
  return res.data || null;
};
