// Helpers for the App usage page: is an installed app version the latest one, and how a user's status reads.

// 'latest' newer than 'current'? Dotted numeric compare ('2.10' > '2.9'), the same rule the mobile app uses to
// decide whether to ask for an update.
export const isNewerVersion = (latestVersion, currentVersion) => {
  if (!latestVersion || !currentVersion) return false;
  const latestParts = String(latestVersion).split('.').map(Number);
  const currentParts = String(currentVersion).split('.').map(Number);
  const length = Math.max(latestParts.length, currentParts.length);
  for (let i = 0; i < length; i++) {
    const latest = latestParts[i] || 0;
    const current = currentParts[i] || 0;
    if (latest > current) return true;
    if (latest < current) return false;
  }
  return false;
};

export const VERSION_STATE = {
  LATEST: 'LATEST',
  OLD: 'OLD',
  UNKNOWN: 'UNKNOWN',
};

// What the user is running compared with the newest release. A version we can't compare (missing, or not dotted
// numbers) is UNKNOWN rather than guessed at.
export const getVersionState = (userVersion, latestVersion) => {
  if (!userVersion || !latestVersion || Number.isNaN(Number(String(userVersion).split('.')[0]))) {
    return VERSION_STATE.UNKNOWN;
  }
  return isNewerVersion(latestVersion, userVersion) ? VERSION_STATE.OLD : VERSION_STATE.LATEST;
};

// An account is Active (it can log in) or Inactive (the admin switched its login off, e.g. a teacher who left). The
// backend calls that flag "blocked". How long ago someone last logged in is shown as the last-login time, not as a status.
export const ACCESS_META = {
  ACTIVE: { label: 'Active', color: '#2e7d32', background: '#e8f5e9' },
  INACTIVE: { label: 'Inactive', color: '#ffffff', background: '#c62828' },
};

export const getAccessMeta = blocked => (blocked ? ACCESS_META.INACTIVE : ACCESS_META.ACTIVE);

// Last login: normal within a week, amber up to a month, red after that. Grey when there is none.
export const getLastLoginColor = days => {
  if (days === null || days === undefined || days < 0) return '#6b778a';
  if (days <= 7) return '#6b778a';
  return days <= 30 ? '#b26a00' : '#c62828';
};

// "Today", "1 day ago", "45 days ago" from the backend's daysSinceLastLogin (-1 when there is no login).
export const formatDaysAgo = days => {
  if (days === null || days === undefined || days < 0) return '--';
  if (days === 0) return 'Today';
  return `${days} day${days === 1 ? '' : 's'} ago`;
};

// A guardian's student as shown on the App usage pills: the API sends a plain name, or - once it also sends the class -
// {name, className}; the class then goes after the name, "NAME (Class)".
export const studentChipLabel = student => {
  if (!student || typeof student === 'string') {
    return student || '';
  }
  const name = student.name || student.studentName || '';
  const className = student.className || student.courseName || '';
  return className ? `${name} (${className})` : name;
};
